## Common Patterns

### Hydration

```typescript
app.get('/api/tasks/:id', async (c) => {
  const id = c.req.param('id');
  const hydrate = c.req.query('hydrate') === 'true';

  const task = await api.get(id, hydrate ? {
    hydrate: { description: true, design: true }
  } : undefined);

  return c.json(task);
});
```

### Actor from Header

```typescript
app.post('/api/features', async (c) => {
  const actor = c.req.header('X-Actor') || defaultActorId;
  const body = await c.req.json();

  const feature = await api.create({
    type: 'feature',
    ...body,
    createdBy: actor,
  });

  return c.json(feature, 201);
});
```

### Search Endpoint

```typescript
app.get('/api/search', async (c) => {
  const q = c.req.query('q');
  const types = c.req.query('types')?.split(',');

  if (!q) {
    return c.json({ error: 'Query required' }, 400);
  }

  const results = await api.search(q, { type: types });
  return c.json(results);
});
```

