  ].join(' '),
  warning: [
    'bg-[var(--color-warning-bg)] text-[var(--color-warning-700)]',
    'dark:bg-[var(--color-warning-bg)] dark:text-[var(--color-warning-text)]',
  ].join(' '),
  error: [
