  ].join(' '),
  outline: [
    'bg-transparent border border-[var(--color-border)] text-[var(--color-text-secondary)]',
    'dark:border-[var(--color-border)] dark:text-[var(--color-text-secondary)]',
  ].join(' '),
};

const sizeStyles = {
