};

export const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  ({ className = '', variant = 'default', size = 'md', ...props }, ref) => {
    return (
      <span
        ref={ref}
        className={[
          'inline-flex items-center font-medium rounded-md whitespace-nowrap',
          variantStyles[variant],
