#### Types

```typescript
interface Setting {
  key: string;
  value: unknown;
  updatedAt: string;
}

interface ServerAgentDefaults {
  defaultExecutablePaths: Record<string, string>; // provider -> path
  /**
   * Ordered list of executable names/paths for rate limit fallback, applied
   * only to workers without an explicit `executablePath`. Assumes one shared
   * plan: a limit on any entry marks the whole chain. See "Fallback Chain
   * Semantics".
   */
  fallbackChain?: string[];
}

/**
 * Sync direction for external sync
 */
type SyncDirection = 'push' | 'pull' | 'bidirectional';

/**
 * Provider configuration stored in settings (SQLite, NOT git-tracked)
 */
interface ProviderConfig {
  /** Provider name (e.g. 'github', 'linear') */
  provider: string;
  /** Authentication token */
  token?: string;
  /** API base URL (for self-hosted instances) */
  apiBaseUrl?: string;
  /** Default project/repo for this provider */
  defaultProject?: string;
}

/**
 * External sync settings stored in SQLite (tokens, cursors, runtime state)
 */
interface ExternalSyncSettings {
  /** Provider configurations keyed by provider name */
  providers: Record<string, ProviderConfig>;
  /** Sync cursors keyed by provider+project+adapterType */
  syncCursors: Record<string, string>;
  /** Poll interval in milliseconds */
  pollIntervalMs: number;
  /** Default sync direction */
  defaultDirection: SyncDirection;
}
```

